namespace sv_a6c5af8a0f1244cb9d24f34e79939eea.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit, so each user gets independent state.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@implements IDisposable
@inject ThemeService ThemeService

<CascadingValue Value="ThemeService" IsFixed="false">
    @ChildContent
</CascadingValue>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleChanged;
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    private string GetIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleChanged;
    }
}

@page "/settings"

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Theme Mode</label>
    <div class="btn-group d-block" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            var isActive = ThemeService.Theme == mode;
            <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.Theme = mode">
                @mode
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold" for="accent">Accent Color</label>
    <input id="accent" type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="e => ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd"" />
</div>

<p>
    Current: <strong style="color: @ThemeService.AccentColor;">@ThemeService.Theme</strong>
</p>

@code {
    [CascadingParameter] public ThemeService ThemeService { get; set; } = default!;
}

