@page "/settings"

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Theme Mode</label>
    <div class="btn-group d-block" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            var isActive = ThemeService.Theme == mode;
            <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.Theme = mode">
                @mode
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold" for="accent">Accent Color</label>
    <input id="accent" type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="e => ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd"" />
</div>

<p>
    Current: <strong style="color: @ThemeService.AccentColor;">@ThemeService.Theme</strong>
</p>

@code {
    [CascadingParameter] public ThemeService ThemeService { get; set; } = default!;
}

